      this.preMigrationSnapshot(6);this.db.exec('BEGIN IMMEDIATE');try{this.db.exec(INSIGHTS_SCHEMA);this.db.prepare('INSERT INTO schema_migrations VALUES(?,?)').run(6,stamp());this.db.exec('PRAGMA user_version=6; COMMIT;');}catch(error){this.db.exec('ROLLBACK');this.db.close();throw error;}
