  draft(idValue:string):Draft|null {id(idValue);const r=this.db.prepare('SELECT payload FROM drafts WHERE id=?').get(idValue);return r?JSON.parse(r.payload as string):null;}
  saveDraft(token:string,d:Draft):Draft{const a=this.actor(token,'draft');d=structuredClone(d);for(const line of d.lines||[])line.unit=['CASE','CAS','CASES'].includes(line.unit.toUpperCase().trim())?'CASE':line.unit.toUpperCase().trim();validateDraft(d,true);return this.tx(()=>{if(this.db.prepare('SELECT 1 FROM documents WHERE id=?').get(d.id))throw Error('Issued documents are read-only.');const prior=this.draft(d.id);if((prior?.version||0)!==d.version)throw Error('Draft version conflict.');const next={...d,version:d.version+1};this.db.prepare('INSERT INTO drafts VALUES(?,?,?) ON CONFLICT(id) DO UPDATE SET version=excluded.version,payload=excluded.payload').run(next.id,next.version,canonical(next));this.audit(a,'draft-saved',d.id,{version:next.version});return next;});}
  checkPeriod(date:string):void {if(!validDate(date))throw Error('Invalid date.');if(this.db.prepare('SELECT 1 FROM period_locks WHERE period=?').get(date.slice(0,7)))throw Error('Period is locked. Owner/CA correction review is required.');}
