  enqueue(entityId:string,version:number,target:string,payload:unknown):void{const serialized=canonical(payload);this.db.prepare('INSERT INTO sync_outbox(id,entity_id,version,target,payload,payload_hash,state,next_retry) VALUES(?,?,?,?,?,?,?,?)').run(randomUUID(),entityId,version,target,serialized,hash(serialized),'pending',stamp());}
