      this.checkPeriod(d.date);const cutover=this.db.prepare("SELECT payload FROM app_settings WHERE key='migrationCutover'").get();if(cutover){const migration=JSON.parse(String(cutover.payload));if(!migration.openingsConfirmed||d.date<migration.cutoverDate)throw Error('Finish the migration opening reconciliation and use a document date on/after the cutover date.');}const p=this.profile();const compliance=JSON.parse((this.db.prepare("SELECT payload FROM app_settings WHERE key='compliance'").get()?.payload as string)||'null') as CompliancePolicy|null;if(compliance){const errors=logisticsErrors(d,['v4-8','v4-9','v4-10','v4-11','v4-12'].includes(p.templateVersion)?{...compliance,einvoiceApplicable:'unknown'}:compliance);if(errors.length)throw Error(errors.map(e=>e.message).join(' '));const hidden=presentationErrors(d,p,compliance.requiredPrintFields);if(hidden.length)throw Error(hidden.join(' '));for(const flag of compliance.requiredPrintFields||[])if(flag in d.appearance&&!d.appearance[flag as keyof Draft['appearance']])throw Error('A print section required by your reviewed policy is hidden: '+flag);}const errors=reviewIssues(d,p,compliance).filter(x=>x.severity==='error');if(errors.length)throw Error(errors.map(x=>x.message).join('\n'));
      const customer=this.customers().find(c=>c.id===d.customerId&&c.kind==='customer'&&!c.archived);if(!customer)throw Error('Customer not available.');
